def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me_s, last_opp_s = history[-1]
    if n <= 7:
        if last_opp_s == 'D':
            return 'D'
        return 'C'

    last_me = 0 if last_me_s == 'C' else 1
    last_opp = 0 if last_opp_s == 'C' else 1

    opp_c_total = 0
    my_d_total = 0
    for i in range(n):
        pair = history[i]
        if pair[1] == 'C':
            opp_c_total += 1
        if pair[0] == 'D':
            my_d_total += 1

    st_c = [[0, 0], [0, 0]]
    st_n = [[0, 0], [0, 0]]
    my_c_after = [0, 0]
    my_n_after = [0, 0]
    my_c_recent = [0, 0]
    my_n_recent = [0, 0]

    recent_start = n - 12
    if recent_start < 1:
        recent_start = 1

    for i in range(1, n):
        prev = history[i - 1]
        cur = history[i]
        pa = 0 if prev[0] == 'C' else 1
        pb = 0 if prev[1] == 'C' else 1
        ccur = 1 if cur[1] == 'C' else 0

        st_n[pa][pb] += 1
        st_c[pa][pb] += ccur
        my_n_after[pa] += 1
        my_c_after[pa] += ccur

        if i >= recent_start:
            my_n_recent[pa] += 1
            my_c_recent[pa] += ccur

    prior_my0 = 0.80
    prior_my1 = 0.15
    prior_state = ((0.82, 0.65), (0.18, 0.18))

    p_my = [prior_my0, prior_my1]
    for a in (0, 1):
        prior = prior_my0 if a == 0 else prior_my1
        den = my_n_after[a]
        if den == 0:
            p_my[a] = prior
        else:
            all_rate = (my_c_after[a] + 2.0 * prior) / (den + 2.0)
            rec_den = my_n_recent[a]
            if rec_den >= 4:
                rec_rate = (my_c_recent[a] + 2.0 * prior) / (rec_den + 2.0)
                p_my[a] = (2.5 * rec_rate + all_rate) / 3.5
            else:
                p_my[a] = all_rate

    pc = [[0.0, 0.0], [0.0, 0.0]]
    alpha = 7.0 if n < 25 else 4.0

    for a in range(2):
        for b in range(2):
            if my_n_after[a] == 0:
                base = prior_state[a][b]
            else:
                base = p_my[a]

            t = st_n[a][b]
            if t == 0:
                v = base
            else:
                sr = float(st_c[a][b]) / float(t)
                w = float(t)
                if w > 8.0:
                    w = 8.0
                v = (w * sr + alpha * base) / (w + alpha)

            if v < 0.03:
                v = 0.03
            elif v > 0.97:
                v = 0.97
            pc[a][b] = v

    if opp_c_total == 0:
        return 'D'

    rem = 100 - n

    if opp_c_total == n and rem > 25:
        if my_d_total == 0:
            return 'D'
        if p_my[1] > 0.55:
            return 'D'
        if my_d_total >= 3 and last_me == 0:
            return 'D'
        return 'C'

    if rem > 25 and last_opp == 1 and last_me == 0:
        if history[-2][0] == 'C':
            return 'D'

    if rem <= 25:
        horizon = rem
    else:
        horizon = 22

    val = [[0.0, 0.0], [0.0, 0.0]]
    best = [[0, 0], [0, 0]]

    for h in range(1, horizon + 1):
        nval = [[0.0, 0.0], [0.0, 0.0]]
        nbest = [[0, 0], [0, 0]]

        for a in range(2):
            for b in range(2):
                p = pc[a][b]
                q = 1.0 - p

                expC = p * (3.0 + val[0][0]) + q * (0.0 + val[0][1])
                expD = p * (5.0 + val[1][0]) + q * (1.0 + val[1][1])

                if expC >= expD:
                    nval[a][b] = expC
                    nbest[a][b] = 0
                else:
                    nval[a][b] = expD
                    nbest[a][b] = 1

        val = nval
        best = nbest

    if best[last_me][last_opp] == 0:
        return 'C'
    return 'D'
